<script setup lang="ts">
import { computed, ref } from 'vue'
const period=ref('current')
const state=ref('ready')
const fixtures={current:[{id:'bookings',label:'Bookings',value:128,previous:108,unit:'count',better:'higher'},{id:'occupancy',label:'Occupancy',value:84,previous:80.8,unit:'percent',better:'higher'},{id:'response',label:'Response time',value:34,previous:50,unit:'seconds',better:'lower'}],baseline:[{id:'bookings',label:'Bookings',value:108,previous:0,unit:'count',better:'higher'},{id:'occupancy',label:'Occupancy',value:80.8,previous:80.8,unit:'percent',better:'higher'},{id:'response',label:'Response time',value:50,previous:40,unit:'seconds',better:'lower'}]}
const metrics=computed(()=>fixtures[period.value as keyof typeof fixtures])
const number=(n:number)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n)
function value(m:typeof fixtures.current[number]){return number(m.value)+(m.unit==='percent'?'%':m.unit==='seconds'?' s':'')}
function delta(m:typeof fixtures.current[number]){const d=m.value-m.previous;if(m.unit!=='percent'&&m.previous===0)return 'No relative comparison: prior value is zero.';const n=m.unit==='percent'?d:d/m.previous*100;return (n>0?'+':'')+number(n)+(m.unit==='percent'?' percentage points':'%')+' vs previous period'}
function assessment(m:typeof fixtures.current[number]){const d=m.value-m.previous;if(m.unit!=='percent'&&m.previous===0)return 'Not comparable';return d===0?'Unchanged':(m.better==='higher'?d>0:d<0)?'Improved':'Worse'}
function reset(){period.value='current';state.value='ready'}
</script>
<template>
<section class="kpi-cards-demo" aria-label="KPI cards example"><p>Fictitious period snapshots, not live business results.</p><div class="kpi-controls"><label>Sample period<select v-model="period"><option value="current">Current vs previous</option><option value="baseline">Previous vs earlier</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option><option value="error">Error</option></select></label><button type="button" @click="reset">Reset example</button></div><p role="status">{{ state==='ready'?'Showing '+(period==='current'?'current vs previous':'previous vs earlier')+' sample metrics.':state==='loading'?'Loading demonstration. No request is running.':state==='empty'?'No metrics for this sample state.':'Metrics unavailable in this sample state. No live request failed.' }}</p><div v-if="state==='ready'" :key="period" class="kpi-grid"><article v-for="m in metrics" :key="m.id" :aria-label="m.label"><h3>{{ m.label }}</h3><strong class="kpi-value">{{ value(m) }}</strong><p>Prior: {{ number(m.previous) }}{{ m.unit==='percent'?'%':m.unit==='seconds'?' s':'' }}</p><p class="kpi-delta">{{ delta(m) }}</p><span :class="['kpi-assessment',assessment(m)==='Improved'?'good':assessment(m)==='Worse'?'bad':'neutral']">{{ assessment(m) }}</span><small>Better when {{ m.better }}.</small></article></div><div v-else class="kpi-placeholder"><p>{{ state==='loading'?'Values are withheld, not replaced with zero.':state==='empty'?'No value is different from a measured zero.':'The cards are hidden instead of presenting stale values as current.' }}</p><button v-if="state==='error'" type="button" @click="state='ready'">Restore sample data</button></div></section>
</template>
<style scoped>
.kpi-cards-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.kpi-controls{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.kpi-controls label{display:grid;gap:6px;font-size:13px;font-weight:650}.kpi-cards-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1);max-width:100%}.kpi-cards-demo button{padding:8px 10px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.kpi-cards-demo :is(select,button):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.kpi-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;animation:kpi-cards-in .2s ease-out}.kpi-grid article{min-width:0;padding:16px;border:1px solid var(--vp-c-divider);border-radius:10px;background:var(--vp-c-bg-soft);overflow-wrap:anywhere}.kpi-grid h3{margin:0 0 12px;font-size:15px}.kpi-value{font-size:30px;font-variant-numeric:tabular-nums}.kpi-grid p,.kpi-grid small{font-size:12px;line-height:1.5}.kpi-grid small{display:block;margin-top:10px}.kpi-assessment{display:inline-block;padding:4px 7px;border-radius:6px;font-size:12px;font-weight:650}.good{background:#e3f4ea;color:#11643b}.bad{background:#fde8ea;color:#a52432}.neutral{background:var(--vp-c-bg);color:var(--vp-c-text-1)}.kpi-placeholder{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes kpi-cards-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}@media(max-width:850px){.kpi-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.kpi-grid{animation:none}}
</style>
